import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';
import * as THREE from 'three';
import { beltCurveCrossed, beltCurveOpen } from '../src/simulation/primitives.js';
import { createMovementModel } from '../src/simulation/registry.js';
import { assertReadableTiming } from './helpers/display-timing.mjs';

const catalog = JSON.parse(await readFile(new URL('../src/data/movements.json', import.meta.url), 'utf8'));
const X_AXIS = new THREE.Vector3(1, 0, 0);
const Y_AXIS = new THREE.Vector3(0, 1, 0);
const Z_AXIS = new THREE.Vector3(0, 0, 1);

function disposeModel(root) {
  const geometries = new Set();
  const materials = new Set();
  root.traverse((object) => {
    if (object.geometry) geometries.add(object.geometry);
    if (Array.isArray(object.material)) object.material.forEach((material) => materials.add(material));
    else if (object.material) materials.add(object.material);
  });
  geometries.forEach((geometry) => geometry.dispose());
  materials.forEach((material) => material.dispose());
}

function assertTangentContinuous(curve, label) {
  assert.ok(curve?.curves?.length > 1, `${label} is a compound curve`);
  for (let index = 0; index < curve.curves.length; index += 1) {
    const current = curve.curves[index];
    const next = curve.curves[(index + 1) % curve.curves.length];
    const tangentDot = current.getTangent(1).dot(next.getTangent(0));
    assert.ok(tangentDot > 1 - 1e-8, `${label} join ${index + 1} is tangent-continuous`);
  }
}

function assertOpenTangentContinuous(curve, label) {
  assert.ok(curve?.curves?.length > 1, `${label} is a compound curve`);
  for (let index = 0; index < curve.curves.length - 1; index += 1) {
    const current = curve.curves[index];
    const next = curve.curves[index + 1];
    const tangentDot = current.getTangent(1).dot(next.getTangent(0));
    assert.ok(tangentDot > 1 - 1e-8, `${label} join ${index + 1} is tangent-continuous`);
  }
}

function assertClosedIndexedGeometry(geometry, label) {
  assert.ok(geometry.index, `${label} is indexed`);
  const edgeCounts = new Map();
  const indices = geometry.index.array;
  const positions = geometry.attributes.position;
  const welded = Array.from({ length: positions.count }, (_, index) => (
    [positions.getX(index), positions.getY(index), positions.getZ(index)]
      .map((value) => Math.round(value * 1e6)).join(',')
  ));
  for (let index = 0; index < indices.length; index += 3) {
    const triangle = [indices[index], indices[index + 1], indices[index + 2]];
    for (const [first, second] of [
      [triangle[0], triangle[1]],
      [triangle[1], triangle[2]],
      [triangle[2], triangle[0]],
    ]) {
      const a = welded[first];
      const b = welded[second];
      const key = a < b ? `${a}:${b}` : `${b}:${a}`;
      edgeCounts.set(key, (edgeCounts.get(key) ?? 0) + 1);
    }
  }
  assert.ok([...edgeCounts.values()].every((count) => count === 2),
    `${label} has no open or missing tooth surfaces`);
}

function assertOutwardClosedGeometry(geometry, label) {
  assertClosedIndexedGeometry(geometry, label);
  const positions = geometry.attributes.position;
  const indices = geometry.index.array;
  let signedVolume = 0;
  for (let index = 0; index < indices.length; index += 3) {
    const first = new THREE.Vector3().fromBufferAttribute(positions, indices[index]);
    const second = new THREE.Vector3().fromBufferAttribute(positions, indices[index + 1]);
    const third = new THREE.Vector3().fromBufferAttribute(positions, indices[index + 2]);
    signedVolume += first.dot(second.clone().cross(third)) / 6;
  }
  assert.ok(signedVolume > 0, `${label} triangle winding faces outward`);
}

function segmentIntersection2D(first, second) {
  const endpoint = (curve, t) => {
    if (typeof curve.getPoint === 'function') return curve.getPoint(t);
    return (t === 0 ? curve.v1 : curve.v2).clone();
  };
  const firstStart = endpoint(first, 0);
  const firstEnd = endpoint(first, 1);
  const secondStart = endpoint(second, 0);
  const secondEnd = endpoint(second, 1);
  const p = firstStart;
  const q = secondStart;
  const r = firstEnd.clone().sub(firstStart);
  const s = secondEnd.clone().sub(secondStart);
  const cross = (left, right) => left.x * right.y - left.y * right.x;
  const denominator = cross(r, s);
  if (Math.abs(denominator) < 1e-10) return null;
  const difference = q.clone().sub(p);
  const t = cross(difference, s) / denominator;
  const u = cross(difference, r) / denominator;
  if (t <= 0 || t >= 1 || u <= 0 || u >= 1) return null;
  const intersection = typeof first.getPoint === 'function'
    ? first.getPoint(t)
    : firstStart.clone().lerp(firstEnd, t);
  intersection.otherPoint = typeof second.getPoint === 'function'
    ? second.getPoint(u)
    : secondStart.clone().lerp(secondEnd, u);
  intersection.parameters = { first: t, second: u };
  return intersection;
}

test('open and crossed belt primitives use exact common tangents', () => {
  const centerA = new THREE.Vector2(-1.45, 0);
  const centerB = new THREE.Vector2(1.45, 0);
  assertTangentContinuous(
    beltCurveOpen(centerA, centerB, 0.532, 1.012),
    'unequal-radius open belt',
  );
  assertTangentContinuous(
    beltCurveCrossed(centerA, centerB, 0.62, 0.84),
    'unequal-radius crossed belt',
  );
});

test('movements 1 and 2 use one no-slip belt with the correct direction', () => {
  for (const [movementIndex, crossed] of [[0, false], [1, true]]) {
    const model = createMovementModel(catalog.movements[movementIndex]);
    const { belt, driven, driver } = model.root.userData.blocks;
    const state = model.root.userData.kinematics;
    assert.ok(model.root.userData.cameraDistanceScale >= 1.3,
      `movement ${movementIndex + 1} keeps both pulley rims inside the initial view`);
    assert.equal(
      model.root.userData.mechanism,
      crossed
        ? 'single-crossed-belt-opposite-direction-pulley-drive'
        : 'single-open-belt-same-direction-pulley-drive',
    );
    assert.equal(
      model.root.children.filter((child) => child.userData.curve).length,
      1,
      `movement ${movementIndex + 1} has one physical belt`,
    );
    assert.equal(belt.userData.curve.userData.crossoverLift > 0, crossed);
    assert.ok(
      Math.abs(Math.abs(state.driverAngularSpeed) * state.driverRadius
        - state.beltSpeed) < 1e-12,
      `movement ${movementIndex + 1} driver has no pitch-line slip`,
    );
    assert.ok(
      Math.abs(Math.abs(state.drivenAngularSpeed) * state.drivenRadius
        - state.beltSpeed) < 1e-12,
      `movement ${movementIndex + 1} driven pulley has no pitch-line slip`,
    );
    assert.equal(
      Math.sign(state.driverAngularSpeed * state.drivenAngularSpeed),
      crossed ? -1 : 1,
      `movement ${movementIndex + 1} has the source rotation direction`,
    );

    model.update(0.4, 0.4);
    assert.ok(
      Math.abs(driver.userData.rotor.rotation.z
        - state.driverAngularSpeed * 0.4) < 1e-12,
      `movement ${movementIndex + 1} driver angle follows its stated speed`,
    );
    assert.ok(
      Math.abs(driven.userData.rotor.rotation.z
        - state.drivenAngularSpeed * 0.4) < 1e-12,
      `movement ${movementIndex + 1} driven angle follows its stated speed`,
    );

    if (crossed) {
      const [firstSpan, , secondSpan] = belt.userData.curve.curves;
      assert.ok(
        Math.abs(firstSpan.getPoint(0.5).z - secondSpan.getPoint(0.5).z)
          > 2 * 0.065,
        'movement 2 separates the two strands through the crossover',
      );
    }
    disposeModel(model.root);
  }
});

test('working pulleys expose face indices as well as tread indices', () => {
  const model = createMovementModel(catalog.movements[1]);
  const pulleys = model.root.children.filter(
    (object) => Array.isArray(object.userData.faceIndicators),
  );
  assert.equal(pulleys.length, 2);
  for (const pulley of pulleys) {
    assert.equal(pulley.userData.faceIndicators.length, 2);
    const [front, rear] = pulley.userData.faceIndicators;
    assert.ok(front.position.z * rear.position.z < 0,
      'the rotation index is visible from either pulley face');
    assert.equal(front.parent, pulley.userData.rotor);
    assert.equal(rear.parent, pulley.userData.rotor);
  }
  disposeModel(model.root);
});

test('all movements aim for two seconds while limiting the fastest rotating part', () => {
  for (const movement of catalog.movements) {
    const model = createMovementModel(movement);
    const timing = model.root.userData.animationTiming;
    assert.equal(timing.targetCycleDuration, 2);
    assert.ok(Number.isFinite(timing.authoredCyclePeriod));
    assert.ok(timing.authoredCyclePeriod > 0);
    assert.ok(Number.isFinite(timing.playbackTimeScale));
    assert.ok(timing.playbackTimeScale > 0);
    assert.ok(Math.abs(
      timing.authoredCyclePeriod / timing.playbackTimeScale - timing.displayCycleDuration,
    ) < 1e-12);
    assert.ok(timing.displayCycleDuration >= 2 - 1e-10);
    assertReadableTiming(timing);
    disposeModel(model.root);
  }
});

test('movement 3 belt contacts every pulley in its pulley plane', () => {
  const model = createMovementModel(catalog.movements[2]);
  assert.equal(model.root.userData.mechanism, 'right-angle-guide-pulley-drive');
  const contacts = model.root.userData.beltContacts;
  assert.equal(contacts.length, 4, 'two working pulleys and two guide pulleys are contacted');
  assert.ok(Math.abs(contacts[0].axis.dot(contacts[1].axis)) < 1e-8, 'working shafts are perpendicular');
  for (const [index, contact] of contacts.entries()) {
    const modeledAxis = new THREE.Vector3(0, 0, 1)
      .applyQuaternion(contact.object.quaternion)
      .normalize();
    assert.ok(
      Math.abs(modeledAxis.dot(contact.axis)) > 1 - 1e-8,
      `pulley ${index + 1} axis is normal to its belt contact arc`,
    );
    assert.ok(
      Math.abs(contact.arc.radialStart.length() - contact.radius) < 1e-8,
      `pulley ${index + 1} uses its pitch radius`,
    );
  }
  const belt = model.root.children.find((child) => child.userData.curve);
  assertTangentContinuous(belt.userData.curve, 'movement 3 belt');
  disposeModel(model.root);
});

test('movement 4 is a tangent-continuous crossed drive between intersecting perpendicular shafts', () => {
  const model = createMovementModel(catalog.movements[3]);
  model.update(1, 0.016);
  assert.equal(model.root.userData.mechanism, 'crossed-right-angle-guide-drive');
  const contacts = model.root.userData.beltContacts;
  assert.equal(contacts.length, 4, 'both working pulleys and both side guides are contacted');
  const [driver, driven] = contacts;
  assert.ok(Math.abs(driver.axis.dot(driven.axis)) < 1e-8, 'working shafts are perpendicular');
  const intersection = model.root.userData.shaftIntersection;
  for (const contact of [driver, driven]) {
    const toIntersection = intersection.clone().sub(contact.object.position);
    const offAxis = new THREE.Vector3().crossVectors(toIntersection, contact.axis).length();
    assert.ok(offAxis < 1e-8, 'extended working shaft passes through the common intersection');
  }
  for (const [index, contact] of contacts.entries()) {
    const modeledAxis = new THREE.Vector3(0, 0, 1)
      .applyQuaternion(contact.object.quaternion)
      .normalize();
    assert.ok(
      Math.abs(modeledAxis.dot(contact.axis)) > 1 - 1e-8,
      `movement 4 pulley ${index + 1} is normal to its contact arc`,
    );
    assert.ok(
      Math.abs(contact.arc.radialStart.length() - contact.radius) < 1e-8,
      `movement 4 pulley ${index + 1} uses its pitch radius`,
    );
  }
  const belt = model.root.children.find((child) => child.userData.curve);
  assertTangentContinuous(belt.userData.curve, 'movement 4 belt');
  const crossing = segmentIntersection2D(
    belt.userData.curve.curves[0],
    belt.userData.curve.curves[6],
  );
  assert.ok(crossing, 'the two long belt leaves cross between the driver and side guides');
  assert.ok(Math.abs(crossing.z - crossing.otherPoint.z) > 0.2,
    'the crossed leaves occupy opposite axial offsets instead of self-intersecting');
  assert.ok(Math.abs(driver.arc.sweep) > Math.PI, 'crossed layout produces a major wrap on the driver');
  assert.ok(model.root.userData.drivenWrapTurns > 2,
    'the belt winds more than twice around the perpendicular lower pulley');
  assert.ok(Math.abs(driven.arc.sweep) > Math.PI * 4,
    'the declared lower contact is the complete multi-turn axial wrap');
  const state = model.root.userData.kinematics;
  assert.ok(Math.abs(Math.abs(state.driverAngularSpeed) * state.driverRadius - state.beltSpeed) < 1e-10);
  assert.ok(Math.abs(Math.abs(state.drivenAngularSpeed) * state.drivenRadius - state.beltSpeed) < 1e-10);
  assert.ok(state.driverAngularSpeed * state.drivenAngularSpeed < 0, 'crossed working pulleys turn in opposite signed senses');
  disposeModel(model.root);
});

test('movement 5 keeps one constant-length belt slack until the tensioner makes contact', () => {
  const model = createMovementModel(catalog.movements[4]);
  assert.equal(model.root.userData.mechanism, 'movable-belt-tensioner');
  const lengths = [];
  for (const time of [0.5, 2.5, 3.3, 5, 7.2, 8]) {
    model.update(time, 0.016);
    const belt = [];
    model.root.traverse((object) => {
      if (object.userData.mechanismBelt) belt.push(object);
    });
    assert.equal(belt.length, 1, `movement 5 has one physical belt at t=${time}`);
    assertTangentContinuous(belt[0].userData.curve, `movement 5 belt at t=${time}`);
    lengths.push(belt[0].userData.length);
    assert.equal(model.root.userData.kinematics.beltCount, 1);
  }
  for (const length of lengths) {
    assert.ok(
      Math.abs(length - model.root.userData.nominalBeltLength) < 1e-8,
      'tensioner redirects the belt without stretching it',
    );
  }

  model.update(6, 0);
  let state = model.root.userData.kinematics;
  assert.equal(state.engagement, 0);
  assert.equal(state.transmission, 0);
  assert.equal(state.beltSpeed, 0, 'slack belt does not transmit the rotating driver');
  let belt = model.root.children.find((object) => object.userData.mechanismBelt);
  let clearance = Infinity;
  for (let index = 0; index <= 200; index += 1) {
    clearance = Math.min(
      clearance,
      belt.userData.curve.getPointAt(index / 200).distanceTo(state.idlerCenter),
    );
  }
  assert.ok(clearance > state.idlerPitchRadius + 0.05, 'retracted idler clears the slack belt');

  model.update(0.5, 0);
  state = model.root.userData.kinematics;
  belt = model.root.children.find((object) => object.userData.mechanismBelt);
  const tensionedSpan = model.root.userData.beltContacts.find((contact) => contact.object === model.root.userData.blocks.idler).arc;
  assert.ok(tensionedSpan.sweep > 0.4, 'the idler has a finite contact wrap');
  const contactPoint = tensionedSpan.getPoint(0.5);
  assert.ok(
    Math.abs(contactPoint.distanceTo(state.idlerCenter) - state.idlerPitchRadius) < 1e-8,
    'the belt wraps the pressed idler at its pitch radius',
  );
  assert.equal(state.transmission, 1);
  assert.ok(Math.abs(Math.abs(state.driverAngularSpeed) * state.mainPitchRadius - state.beltSpeed) < 1e-10);
  assert.ok(Math.abs(Math.abs(state.drivenAngularSpeed) * state.drivenRadius - state.beltSpeed) < 1e-10);
  assert.ok(state.driverAngularSpeed * state.drivenAngularSpeed > 0, 'open belt turns both working pulleys in the same signed sense');
  disposeModel(model.root);
});

test('movement 6 uses one attached crossed belt to reverse both lower pulleys', () => {
  const model = createMovementModel(catalog.movements[5]);
  assert.equal(model.root.userData.mechanism, 'vibrating-sector-belt-drive');
  const lengths = [];
  const signedSpeeds = [];
  for (const time of [0, Math.PI / (2 * 1.05), Math.PI / 1.05, 3 * Math.PI / (2 * 1.05)]) {
    model.update(time, 0.016);
    const belts = [];
    model.root.traverse((object) => {
      if (object.userData.mechanismBelt) belts.push(object);
    });
    assert.equal(belts.length, 1, `movement 6 has one physical belt at t=${time}`);
    const belt = belts[0];
    assert.equal(belt.userData.closed, false, 'the belt ends are attached to the rocking sector');
    assert.equal(belt.userData.curve.curves.length, 7, 'sector wraps connect the lever anchors to both leaves, pulley wraps, and lower span');
    assertOpenTangentContinuous(belt.userData.curve, `movement 6 belt at t=${time}`);
    assert.ok(
      belt.userData.curve.getPoint(0).distanceTo(model.root.userData.attachments.left) < 1e-10,
      'left belt end follows its sector attachment',
    );
    assert.ok(
      belt.userData.curve.getPoint(1).distanceTo(model.root.userData.attachments.right) < 1e-10,
      'right belt end follows its sector attachment',
    );
    const crossing = segmentIntersection2D(
      belt.userData.curve.curves[1],
      belt.userData.curve.curves[5],
    );
    assert.ok(crossing, 'the two long belt leaves cross in projection');
    assert.ok(Math.abs(crossing.z - crossing.otherPoint.z) > 0.15,
      'the crossed leaves bow to opposite sides rather than self-intersecting');

    const state = model.root.userData.kinematics;
    lengths.push(state.beltLength);
    signedSpeeds.push(state.leftAngularSpeed);
    assert.ok(Math.abs(Math.abs(state.leftAngularSpeed) * state.lowerPitchRadius - Math.abs(state.beltSpeed)) < 1e-10);
    assert.ok(Math.abs(Math.abs(state.rightAngularSpeed) * state.lowerPitchRadius - Math.abs(state.beltSpeed)) < 1e-10);
    assert.ok(state.leftAngularSpeed * state.rightAngularSpeed >= 0, 'both lower pulleys turn in the same signed sense');
  }
  assert.ok(signedSpeeds[0] * signedSpeeds[2] < 0, 'the lower pulleys reverse when the sector reverses');
  const lengthVariation = (Math.max(...lengths) - Math.min(...lengths)) / model.root.userData.nominalBeltLength;
  assert.ok(lengthVariation < 1e-7, 'sector wrap transfer keeps the attached belt length constant through the stroke');
  disposeModel(model.root);
});

test('movement 7 traverses one belt across loose and reversing coaxial drives', () => {
  const model = createMovementModel(catalog.movements[6]);
  assert.equal(model.root.userData.mechanism, 'reversing-bevel-selector');
  const drive = model.root.userData.coaxialDrive;
  assert.deepEqual(
    drive.lowerPulleys.map((pulley) => pulley.userData.role),
    ['hollow-shaft-b', 'loose-neutral', 'inner-shaft-a'],
  );
  for (const pulley of drive.lowerPulleys) {
    const modeledAxis = Z_AXIS.clone().applyQuaternion(pulley.quaternion).normalize();
    assert.ok(Math.abs(modeledAxis.dot(drive.axis)) > 1 - 1e-8, 'every lower pulley is coaxial');
  }
  assert.ok(
    Math.abs(drive.hollowShaft.position.y - drive.innerShaft.position.y) < 1e-10
      && Math.abs(drive.hollowShaft.position.z - drive.innerShaft.position.z) < 1e-10,
    'shaft a runs inside the coaxial hollow shaft b',
  );

  const [aContact, bContact] = model.root.userData.bevelContacts;
  const axisA = Z_AXIS.clone().applyQuaternion(aContact.input.quaternion).normalize();
  const axisB = Z_AXIS.clone().applyQuaternion(bContact.input.quaternion).normalize();
  const outputAxis = Z_AXIS.clone().applyQuaternion(aContact.output.quaternion).normalize();
  assert.ok(axisA.dot(axisB) < -1 + 1e-8, 'opposed bevel gears A and B face one another');
  assert.ok(Math.abs(axisA.dot(outputAxis)) < 1e-8, 'the output bevel axis is perpendicular');
  assert.equal(aContact.output, bContact.output, 'both side gears mesh with the same upright output gear');
  for (const gear of [aContact.input, bContact.input, aContact.output]) {
    assert.equal(gear.userData.toothProfile, 'back-cone-involute-approximation');
    assert.equal(gear.userData.toothMeshes.length, gear.userData.teeth);
    const radii = gear.userData.toothRadii;
    assert.ok(radii.largeTipRadius > radii.largeRootRadius);
    assert.ok(radii.smallTipRadius > radii.smallRootRadius);
    assert.ok(radii.smallTipRadius < radii.largeTipRadius,
      'each bevel tooth terminates on a smaller conical end rather than a flat box');
    gear.userData.toothMeshes.forEach((tooth, index) => {
      assertClosedIndexedGeometry(tooth.geometry, `movement 7 bevel tooth ${index + 1}`);
    });
  }
  for (const { input, output } of [aContact, bContact]) {
    assert.ok(input.position.distanceTo(output.position) < 1e-12,
      'the pitch cones share one apex rather than facing away from each other');
    assert.ok(Math.abs(input.userData.pitchConeAngle + output.userData.pitchConeAngle - Math.PI / 2) < 1e-12);
    assert.ok(Math.abs(input.userData.outerPitchRadius / input.userData.teeth
      - output.userData.outerPitchRadius / output.userData.teeth) < 1e-12,
    'bevel pitch radii match the actual 18:22 tooth counts');
  }

  const states = new Map();
  for (const [label, time, expectedIndex] of [
    ['neutral', 1, 1],
    ['left', 5, 0],
    ['right', 13, 2],
  ]) {
    model.update(time, 0.016);
    const belts = [];
    model.root.traverse((object) => {
      if (object.userData.selectorBelt) belts.push(object);
    });
    assert.equal(belts.length, 1, `${label} has one physical traversing belt`);
    assert.equal(belts[0].visible && belts[0].userData.active, true);
    assertTangentContinuous(belts[0].userData.curve, `movement 7 ${label} belt`);
    const state = { ...model.root.userData.kinematics };
    assert.equal(state.selectedIndex, expectedIndex);
    assert.equal(state.isShifting, false);
    model.root.updateMatrixWorld(true);
    const beltPlaneX = new THREE.Vector3().setFromMatrixPosition(belts[0].matrixWorld).x;
    assert.ok(
      Math.abs(beltPlaneX - drive.lowerPulleys[expectedIndex].position.x) < 1e-8,
      `${label} belt aligns with the selected lower pulley`,
    );
    states.set(label, state);
  }

  const neutral = states.get('neutral');
  assert.equal(neutral.leftShaftAngularSpeed, 0);
  assert.equal(neutral.rightShaftAngularSpeed, 0);
  assert.equal(neutral.outputAngularSpeed, 0, 'the loose middle pulley disengages the output');
  assert.equal(neutral.neutralPulleyAngularSpeed, neutral.driverAngularSpeed);

  for (const label of ['left', 'right']) {
    const state = states.get(label);
    const selectedShaftSpeed = label === 'left'
      ? state.leftShaftAngularSpeed
      : state.rightShaftAngularSpeed;
    assert.ok(Math.abs(Math.abs(selectedShaftSpeed) * state.pitchRadius - state.beltSpeed) < 1e-10);
    assert.ok(
      Math.abs(state.leftShaftAngularSpeed + state.rightShaftAngularSpeed) < 1e-10,
      'the idle coaxial shaft is back-driven through the opposed bevel gears',
    );
    assert.ok(
      Math.abs(Math.abs(state.outputAngularSpeed) * state.outputGearRadius
        - Math.abs(selectedShaftSpeed) * state.sideGearRadius) < 1e-10,
      'bevel-gear pitch-line speeds match',
    );
  }
  assert.ok(
    states.get('left').outputAngularSpeed * states.get('right').outputAngularSpeed < 0,
    'selecting the opposite fast pulley reverses the upright output',
  );
  disposeModel(model.root);
});

test('movement 8 renders one belt and obeys the active pulley ratio', () => {
  const model = createMovementModel(catalog.movements[7]);
  for (const time of [1, 4.5, 8.7, 13.2]) {
    model.update(time, 0.016);
    const selectorBelts = model.root.children.filter((child) => child.userData.selectorBelt);
    assert.equal(selectorBelts.length, 4, 'the four steps in the engraving are modeled');
    assert.equal(
      selectorBelts.filter((belt) => belt.visible && belt.userData.active).length,
      1,
      `one belt is installed at t=${time}`,
    );
    selectorBelts.forEach((belt, index) => {
      assertTangentContinuous(belt.userData.curve, `movement 8 ratio ${index + 1}`);
    });
    const state = model.root.userData.kinematics;
    const expectedRatio = state.driverRadius / state.drivenRadius;
    assert.ok(Math.abs(state.drivenAngularSpeed / state.driverAngularSpeed - expectedRatio) < 1e-10);
    assert.ok(Math.abs(Math.abs(state.beltSpeed) - Math.abs(state.driverAngularSpeed) * state.driverRadius) < 1e-10);
    assert.ok(Math.abs(Math.abs(state.beltSpeed) - Math.abs(state.drivenAngularSpeed) * state.drivenRadius) < 1e-10);
  }

  // A marker advances by physical distance, not by the local parameter of a
  // line or pulley arc.  Sampling every join permanently guards against the
  // visible speed jump that occurs when a marker is parameterized per segment.
  const selectorBelts = model.root.children.filter(
    (child) => child.userData.selectorBelt,
  );
  for (const [beltIndex, belt] of selectorBelts.entries()) {
    const marker = belt.children[1];
    const sampleCount = 4096;
    const expectedStep = belt.userData.length / sampleCount;
    let previous = null;
    let minimumStep = Infinity;
    let maximumStep = 0;
    for (let index = 0; index <= sampleCount; index += 1) {
      belt.userData.update(index / sampleCount);
      const current = marker.position.clone();
      if (previous) {
        const step = current.distanceTo(previous);
        minimumStep = Math.min(minimumStep, step);
        maximumStep = Math.max(maximumStep, step);
      }
      previous = current;
    }
    assert.ok(
      maximumStep / minimumStep < 1.002,
      `movement 8 ratio ${beltIndex + 1} marker has uniform arc-length speed`,
    );
    assert.ok(
      Math.abs((minimumStep + maximumStep) / 2 - expectedStep)
        < expectedStep * 0.001,
      `movement 8 ratio ${beltIndex + 1} marker speed matches belt distance`,
    );
  }
  disposeModel(model.root);
});

test('movement 9 continuously traverses one belt across opposed cone pulleys', () => {
  const model = createMovementModel(catalog.movements[8]);
  assert.equal(model.root.userData.mechanism, 'opposed-cone-variable-speed-drive');
  const states = [];
  const lengths = [];
  for (const time of [0, Math.PI, 2 * Math.PI, 3 * Math.PI]) {
    model.update(time, 0.016);
    const belts = [];
    model.root.traverse((object) => {
      if (object.userData.mechanismBelt) belts.push(object);
    });
    assert.equal(belts.length, 1, `movement 9 has one physical belt at t=${time}`);
    assert.equal(belts[0].visible && belts[0].userData.active, true);
    assertTangentContinuous(belts[0].userData.curve, `movement 9 belt at t=${time}`);
    const state = { ...model.root.userData.kinematics };
    assert.ok(state.level > 0 && state.level < 1, 'the belt remains on both cone faces');
    assert.ok(
      Math.abs(state.drivenAngularSpeed / state.driverAngularSpeed - state.ratio) < 1e-10,
      'the instantaneous speed ratio follows the two contact radii',
    );
    assert.ok(
      Math.abs(Math.abs(state.driverAngularSpeed) * state.driverPitchRadius - state.beltSpeed) < 1e-10,
    );
    assert.ok(
      Math.abs(Math.abs(state.drivenAngularSpeed) * state.drivenPitchRadius - state.beltSpeed) < 1e-10,
    );
    assert.ok(
      Math.abs(state.driverPitchRadius + state.drivenPitchRadius - 1.494) < 1e-10,
      'the opposed linear cones keep the sum of contact radii constant',
    );
    for (let index = 0; index <= 20; index += 1) {
      assert.ok(
        Math.abs(belts[0].userData.curve.getPoint(index / 20).z - state.beltZ) < 1e-10,
        'the traversing belt stays in one plane normal to both shafts',
      );
    }
    const contacts = model.root.userData.beltContacts;
    assert.equal(contacts.length, 2);
    assert.ok(Math.abs(contacts[0].radius - state.driverPitchRadius) < 1e-10);
    assert.ok(Math.abs(contacts[1].radius - state.drivenPitchRadius) < 1e-10);
    assert.ok(Math.abs(contacts[0].axis.dot(contacts[1].axis)) > 1 - 1e-10);
    states.push(state);
    lengths.push(state.beltLength);
  }
  assert.ok(states[1].ratio > 2, 'one end of the cones produces speed increase');
  assert.ok(states[3].ratio < 0.5, 'the other end produces speed reduction');
  assert.ok(
    (Math.max(...lengths) - Math.min(...lengths)) / lengths[0] < 0.012,
    'belt-length variation stays within the small compliance inherent in the cone drive',
  );
  disposeModel(model.root);
});

