test('movement 49 couples equal bevel gears through real pivoted pawls and keyed carriers', () => {
  const model = createMovementModel(catalog.movements[48]);
  assert.equal(model.root.userData.mechanism, 'equal-miter-gears-with-contact-driven-opposed-pawls');
  const b = model.root.userData.blocks, g = model.root.userData.geometry;
  assert.equal(b.rightGear.userData.teeth, b.leftGear.userData.teeth);
  assert.equal(b.rightGear.userData.teeth, b.outputGear.userData.teeth);
  assert.ok(Math.abs(g.pitchConeAngle - Math.PI / 4) < 1e-12);
  assert.equal(b.rightCarrier.userData.parts.ratchet.parent, b.rightGear.userData.rotor);
  assert.equal(b.leftCarrier.userData.parts.ratchet.parent, b.leftGear.userData.rotor);
  assert.ok(Math.abs(model.root.userData.animationTiming.authoredCyclePeriod - g.cycleDuration) < 1e-12);
  for (let pose = 0; pose <= 128; pose += 1) {
    model.update(3 * g.cycleDuration * pose / 128, 0);
    const state = model.root.userData.ratchetState;
    assert.ok(Math.abs(b.shaft.userData.rotor.rotation.z - state.inputAngle) < 1e-12);
    assert.ok(Math.abs(b.rightCarrier.userData.rotor.rotation.z - state.inputAngle) < 1e-12);
    assert.ok(Math.abs(b.leftCarrier.userData.rotor.rotation.z + state.inputAngle) < 1e-12);
    assert.ok(Math.abs(b.rightGear.userData.rotor.rotation.z - Math.PI / 2 - state.advance) < 1e-12);
    assert.ok(Math.abs(b.leftGear.userData.rotor.rotation.z - b.rightGear.userData.rotor.rotation.z) < 1e-12);
    assert.ok(Math.abs(b.outputGear.userData.rotor.rotation.z + Math.PI / g.teeth + state.advance) < 1e-12);
    assert.ok(Math.abs(b.outputShaft.userData.rotor.rotation.z - b.outputGear.userData.rotor.rotation.z) < 1e-12);
    assert.ok(Math.abs(b.rightCarrier.userData.parts.pawl.rotation.z - state.rightPawlAngle) < 1e-12);
    assert.ok(Math.abs(b.leftCarrier.userData.parts.pawl.rotation.z - state.leftPawlAngle) < 1e-12);
    for (const side of [-1, 1]) {
      const contact = new THREE.Vector3(side * 0.78, 0.78, 0);
      const inputVelocity = new THREE.Vector3(side * -state.outputAngularSpeed, 0, 0).cross(contact);
      const outputVelocity = new THREE.Vector3(0, state.outputAngularSpeed, 0).cross(contact);
      assert.ok(inputVelocity.distanceTo(outputVelocity) < 1e-12, 'both pitch contacts have matching surface velocities');
    }
  }
  disposeModel(model.root);
});

for (const id of [50, 51]) test('movement ' + id + ' wires the bored curved forks to its solved universal-joint motion', () => {
  const model = createMovementModel(catalog.movements[id - 1]);
  const { inputYoke, outputYoke, middle, leftCross, rightCross } = model.root.userData.blocks;
  assert.equal(model.root.userData.mechanism, id === 50
    ? 'compact-double-cardan-with-bored-curved-forks' : 'single-cardan-with-bored-curved-forks');
  assert.equal(Boolean(middle), id === 50);
  assert.equal(Boolean(rightCross), id === 50);
  assert.equal(inputYoke.userData.parts.eyes.length, 2);
  assert.equal(outputYoke.userData.parts.eyes.length, 2);
  if (middle) assert.equal(middle.userData.parts.eyes.length, 4);
  for (let sample = 0; sample <= 64; sample += 1) {
    const time = 3 * model.root.userData.geometry.cyclePeriod * sample / 64;
    const expected = model.root.userData.stateAtTime(time); model.update(time, 0); model.root.updateMatrixWorld(true);
    assert.ok(Math.abs(inputYoke.userData.rotor.rotation.z - expected.inputAngle) < 1e-12);
    assert.ok(Math.abs(outputYoke.userData.rotor.rotation.z - expected.outputAngle) < 1e-12);
    assert.ok(leftCross.quaternion.angleTo(expected.left.quaternion) < 1e-7);
    assert.ok(expected.outputAngularSpeed > 0);
    if (middle) {
      assert.ok(Math.abs(middle.userData.rotor.rotation.z - expected.middleAngle) < 1e-12);
      assert.ok(rightCross.quaternion.angleTo(expected.right.quaternion) < 1e-7);
      assert.ok(Math.abs(expected.outputAngularSpeed - expected.inputAngularSpeed) < 1e-12);
    }
  }
  disposeModel(model.root);
});

