test('movement 71 uses B’s two-notched inner guard to index C’s ten studs', () => {
  const model = createMovementModel(catalog.movements[70]);
  assert.equal(
    model.root.userData.mechanism,
    'internal-guard-two-notch-tappet-ten-stud-index',
  );
  assert.equal(model.root.userData.fidelity, 'authored');
  const {
    driven,
    drivenBody,
    drivenIndicator,
    drivenShaft,
    driver,
    driverBody,
    driverIndicator,
    driverShaft,
    guardSegments,
    studs,
    tappet,
  } = model.root.userData.blocks;
  const geometry = model.root.userData.geometry;

  assert.equal(driverBody.parent, driver.userData.rotor);
  assert.equal(driverBody.userData.driverWheelBBody, true);
  assert.equal(driverIndicator.userData.driverRotationIndicator, true);
  assert.equal(guardSegments.length, 2,
    'B has two guard arcs separated by distinct entering and leaving notches');
  for (const [index, segment] of guardSegments.entries()) {
    assert.equal(segment.parent, driver.userData.rotor);
    assert.equal(segment.userData.guardRimSegment, true);
    assert.equal(segment.userData.index, index);
  }
  assert.equal(tappet.parent, driver.userData.rotor);
  assert.equal(tappet.userData.fixedTappetA, true);
  let tappetCount = 0;
  model.root.traverse((object) => {
    if (object.userData.fixedTappetA) tappetCount += 1;
  });
  assert.equal(tappetCount, 1, 'B carries exactly one tappet A');

  assert.equal(drivenBody.parent, driven.userData.rotor);
  assert.equal(drivenBody.userData.studdedIndexDiskBody, true);
  assert.equal(drivenIndicator.userData.drivenRotationIndicator, true);
  assert.equal(studs.length, 10);
  assert.equal(driven.userData.studCount, geometry.studCount);
  assert.equal(driven.userData.studPitch, geometry.studPitch);
  for (const [index, stud] of studs.entries()) {
    assert.equal(stud.userData.indexingStud, true);
    assert.equal(stud.userData.index, index);
    assert.equal(stud.userData.radius, geometry.studRadius);
    assert.equal(stud.userData.orbitRadius, geometry.studOrbitRadius);
  }
  for (const rotor of [driver, driverShaft, driven, drivenShaft]) {
    assert.ok(rotor.userData.axis.distanceTo(geometry.axis) < 1e-12);
  }
  assert.ok(Math.abs(geometry.driverCenter.distanceTo(geometry.drivenCenter)
    - geometry.centerDistance) < 1e-12);

  assert.equal(geometry.studCount, 10);
  assert.ok(Math.abs(geometry.studPitch
    - geometry.fullTurn / geometry.studCount) < 1e-12);
  assert.ok(Math.abs(geometry.halfStudPitch
    - geometry.studPitch / 2) < 1e-12);
  assert.equal(geometry.studMountPhase, geometry.halfStudPitch);
  assert.ok(Math.abs(geometry.tappetContactOffset
    - geometry.tappetHalfWidth - geometry.studRadius) < 1e-12);
  assert.ok(Math.abs(geometry.contactPhaseSpan
    - geometry.contactDriverAngleSpan / geometry.fullTurn) < 1e-12);
  assert.ok(Math.abs(geometry.contactEndPhase
    - geometry.contactStartPhase - geometry.contactPhaseSpan) < 1e-12);
  assert.ok(Math.abs(geometry.lockedStudCenterDistance - Math.hypot(
    geometry.centerDistance
      - geometry.studOrbitRadius * Math.cos(geometry.halfStudPitch),
    geometry.studOrbitRadius * Math.sin(geometry.halfStudPitch),
  )) < 1e-12);
  assert.ok(Math.abs(geometry.guardInnerRadius
    - geometry.studRadius - geometry.lockedStudCenterDistance) < 1e-12,
  'the inner circumference is tangent to both adjacent studs during dwell');
  assert.ok(geometry.guardOuterRadius > geometry.guardInnerRadius);
  assert.ok(geometry.enteringNotchStart < geometry.enteringNotchEnd);
  assert.ok(geometry.enteringNotchEnd < 0);
  assert.ok(geometry.leavingNotchStart > 0);
  assert.ok(geometry.leavingNotchStart < geometry.leavingNotchEnd);
  assert.ok(geometry.enteringNotchEnd < geometry.leavingNotchStart,
    'an intact central guard bridge separates the two notches');

  assert.equal(driver.userData.guardInnerRadius, geometry.guardInnerRadius);
  assert.equal(driver.userData.guardOuterRadius, geometry.guardOuterRadius);
  assert.equal(driver.userData.enteringNotchStart,
    geometry.enteringNotchStart);
  assert.equal(driver.userData.enteringNotchEnd, geometry.enteringNotchEnd);
  assert.equal(driver.userData.leavingNotchStart,
    geometry.leavingNotchStart);
  assert.equal(driver.userData.leavingNotchEnd, geometry.leavingNotchEnd);
  assert.equal(guardSegments[0].userData.startAngle,
    geometry.enteringNotchEnd);
  assert.equal(guardSegments[0].userData.endAngle,
    geometry.leavingNotchStart);
  assert.equal(guardSegments[1].userData.startAngle,
    geometry.leavingNotchEnd);
  assert.equal(guardSegments[1].userData.endAngle,
    geometry.enteringNotchStart + geometry.fullTurn);
  for (const segment of guardSegments) {
    for (const point of segment.userData.outerArc) {
      assert.ok(Math.abs(point.length() - geometry.guardOuterRadius) < 1e-12);
    }
    for (const point of segment.userData.innerArc) {
      assert.ok(Math.abs(point.length() - geometry.guardInnerRadius) < 1e-12);
    }
  }

  model.root.updateMatrixWorld(true);
  const driverBodyBounds = new THREE.Box3().setFromObject(driverBody);
  const drivenBodyBounds = new THREE.Box3().setFromObject(drivenBody);
  const tappetBounds = new THREE.Box3().setFromObject(tappet);
  assert.ok(driverBodyBounds.max.z < drivenBodyBounds.min.z,
    'the overlapping wheel plates occupy separate axial planes');
  assert.ok(tappetBounds.min.z > drivenBodyBounds.max.z);
  for (const segment of guardSegments) {
    const guardBounds = new THREE.Box3().setFromObject(segment);
    assert.ok(guardBounds.min.z > drivenBodyBounds.max.z,
      'B’s guard and tappet share the raised interaction plane');
  }
  for (const stud of studs) {
    const studBounds = new THREE.Box3().setFromObject(stud);
    assert.ok(studBounds.min.z < geometry.guardPlaneZ);
    assert.ok(studBounds.max.z > geometry.guardPlaneZ,
      'every stud projects from C into B’s raised guard plane');
  }

  const atPhase = (phase, cycleIndex = 0) => model.root.userData.stateAtTime(
    ((cycleIndex + phase - geometry.initialCyclePhase) * geometry.fullTurn)
      / geometry.driverAngularSpeed,
  );
  const fullLockBefore = atPhase(0.05);
  const transitionLockBefore = atPhase(0.1);
  const entry = atPhase(geometry.contactStartPhase);
  const midIndex = atPhase(
    geometry.contactStartPhase + geometry.contactPhaseSpan / 2,
  );
  const exit = atPhase(geometry.contactEndPhase);
  const transitionLockAfter = atPhase(0.24);
  const fullLockAfter = atPhase(0.5);

  assert.equal(fullLockBefore.stage, 'guard-locked-before-index');
  assert.equal(fullLockBefore.indexing, false);
  assert.equal(fullLockBefore.drivenLocked, true);
  assert.deepEqual(fullLockBefore.guardCandidateStudIndices, [9, 0]);
  assert.deepEqual(fullLockBefore.guardLockStudIndices, [9, 0]);
  assert.equal(fullLockBefore.guardStudContacts.length, 2);
  assert.equal(fullLockBefore.drivenAngle, 0);
  assert.equal(fullLockBefore.drivenAngularSpeed, 0);
  for (const contact of fullLockBefore.guardStudContacts) {
    assert.ok(contact.error < 1e-12);
    assert.ok(Math.abs(contact.guardPoint.clone().sub(
      geometry.driverCenter,
    ).setZ(0).length() - geometry.guardInnerRadius) < 1e-12);
  }
  assert.deepEqual(transitionLockBefore.guardCandidateStudIndices, [9, 0]);
  assert.deepEqual(transitionLockBefore.guardLockStudIndices, [9],
    'the leaving stud holds C while the struck stud clears the upper notch');
  assert.equal(transitionLockBefore.drivenLocked, true);

  assert.equal(entry.stage, 'tappet-index');
  assert.equal(entry.indexing, true);
  assert.equal(entry.eventFraction, 0);
  assert.equal(entry.activeStudIndex, 0);
  assert.equal(entry.leavingStudIndex, 9);
  assert.equal(entry.enteringStudIndex, 1);
  assert.deepEqual(entry.guardLockStudIndices, []);
  assert.equal(entry.guardLockEngaged, false);
  assert.equal(entry.tappetStudEngaged, true);
  assert.ok(entry.driverAngularSpeed > 0);
  assert.ok(entry.drivenAngularSpeed < 0);
  assert.ok(Math.abs(entry.drivenAdvanceAngle) < 1e-12);
  assert.ok(entry.tappetContactError < 1e-12);
  assert.ok(entry.tappetNormalVelocityError < 1e-12);

  assert.equal(midIndex.stage, 'tappet-index');
  assert.equal(midIndex.tappetStudEngaged, true);
  assert.equal(midIndex.guardLockEngaged, false);
  assert.ok(midIndex.drivenAdvanceAngle < 0);
  assert.ok(midIndex.drivenAdvanceAngle > -geometry.studPitch);
  assert.ok(midIndex.drivenAngularSpeed < 0);
  assert.ok(midIndex.tappetContactProjection >= 0.2 - 1e-12);
  assert.ok(midIndex.tappetContactProjection
    <= geometry.tappetLength + 1e-12);
  assert.ok(midIndex.tappetContactError < 1e-12);
  assert.ok(midIndex.tappetNormalVelocityError < 1e-12);

  const enteringNotchWorldAngle = midIndex.driverAngle
    + (geometry.enteringNotchStart + geometry.enteringNotchEnd) / 2;
  const leavingNotchWorldAngle = midIndex.driverAngle
    + (geometry.leavingNotchStart + geometry.leavingNotchEnd) / 2;
  assert.ok(Math.sin(enteringNotchWorldAngle) > 0,
    'the entering stud uses the upper notch during the indexed step');
  assert.ok(Math.sin(leavingNotchWorldAngle) < 0,
    'the leaving stud uses the lower notch during the indexed step');

  assert.equal(exit.stage, 'tappet-index');
  assert.ok(Math.abs(exit.eventFraction - 1) < 1e-12);
  assert.ok(Math.abs(exit.drivenAdvanceAngle + geometry.studPitch) < 1e-12);
  assert.ok(exit.tappetContactError < 1e-12);
  assert.ok(exit.tappetNormalVelocityError < 1e-12);
  assert.equal(transitionLockAfter.stage, 'guard-locked-after-index');
  assert.deepEqual(transitionLockAfter.guardCandidateStudIndices, [0, 1]);
  assert.deepEqual(transitionLockAfter.guardLockStudIndices, [0]);
  assert.equal(transitionLockAfter.drivenLocked, true);
  assert.equal(fullLockAfter.drivenAngle, -geometry.studPitch);
  assert.deepEqual(fullLockAfter.guardLockStudIndices, [0, 1]);
  assert.equal(fullLockAfter.guardStudContacts.length, 2);

  const samePhaseNextCycle = atPhase(0.05, 1);
  assert.ok(Math.abs(samePhaseNextCycle.driverAngle
    - fullLockBefore.driverAngle - geometry.fullTurn) < 1e-12);
  assert.ok(Math.abs(samePhaseNextCycle.drivenAngle
    - fullLockBefore.drivenAngle + geometry.studPitch) < 1e-12);
  assert.equal(samePhaseNextCycle.activeStudIndex, 1);
  assert.ok(Math.abs(
    (samePhaseNextCycle.drivenAngle - fullLockBefore.drivenAngle)
      / (samePhaseNextCycle.driverAngle - fullLockBefore.driverAngle)
      + 1 / geometry.studCount,
  ) < 1e-12,
  'one counterclockwise turn of B advances C clockwise by one stud pitch');
  const afterTenCycles = atPhase(0.05, geometry.studCount);
  assert.ok(Math.abs(afterTenCycles.drivenAngle
    - fullLockBefore.drivenAngle + geometry.fullTurn) < 1e-11);

  const planarStudFromDriver = (state, index) => {
    const studAngle = geometry.studMountPhase + index * geometry.studPitch
      + state.drivenAngle;
    return new THREE.Vector2(
      geometry.drivenCenter.x
        + Math.cos(studAngle) * geometry.studOrbitRadius
        - geometry.driverCenter.x,
      geometry.drivenCenter.y
        + Math.sin(studAngle) * geometry.studOrbitRadius
        - geometry.driverCenter.y,
    );
  };
  for (let sample = 0; sample <= 240; sample += 1) {
    const phase = geometry.contactStartPhase
      + geometry.contactPhaseSpan * sample / 240;
    const state = atPhase(phase);
    const tappetDirection = new THREE.Vector2(
      Math.cos(state.driverAngle),
      Math.sin(state.driverAngle),
    );
    const tappetNormal = new THREE.Vector2(
      -tappetDirection.y,
      tappetDirection.x,
    );
    const activeLocal = planarStudFromDriver(
      state,
      state.activeStudIndex,
    ).rotateAround(new THREE.Vector2(), -state.driverAngle);
    assert.ok(activeLocal.length() + geometry.studRadius
      <= geometry.guardInnerRadius + 1e-12,
    'the struck stud remains inside, rather than penetrating, B’s guard');

    for (const [kind, index, notchStart, notchEnd] of [
      [
        'leaving',
        state.leavingStudIndex,
        geometry.leavingNotchStart,
        geometry.leavingNotchEnd,
      ],
      [
        'entering',
        state.enteringStudIndex,
        geometry.enteringNotchStart,
        geometry.enteringNotchEnd,
      ],
    ]) {
      const local = planarStudFromDriver(state, index).rotateAround(
        new THREE.Vector2(),
        -state.driverAngle,
      );
      const distance = local.length();
      if (
        distance + geometry.studRadius >= geometry.guardInnerRadius - 1e-12
        && distance - geometry.studRadius
          <= geometry.guardOuterRadius + 1e-12
      ) {
        const centerAngle = Math.atan2(local.y, local.x);
        const angularExtent = Math.asin(geometry.studRadius / distance);
        assert.ok(centerAngle - angularExtent
          >= notchStart + geometry.notchAngularClearance - 5e-5,
        `the ${kind} stud circle clears the first corner of its notch`);
        assert.ok(centerAngle + angularExtent
          <= notchEnd - geometry.notchAngularClearance + 5e-5,
        `the ${kind} stud circle clears the second corner of its notch`);
      }
    }

    for (let index = 0; index < geometry.studCount; index += 1) {
      if (index === state.activeStudIndex) continue;
      const relative = planarStudFromDriver(state, index);
      const projection = relative.dot(tappetDirection);
      if (
        projection >= 0.2 - geometry.studRadius
        && projection <= geometry.tappetLength + geometry.studRadius
      ) {
        assert.ok(Math.abs(relative.dot(tappetNormal))
          >= geometry.tappetContactOffset + 0.3,
        'A clears every non-active stud');
      }
    }
  }

  for (let sample = 0; sample <= 600; sample += 1) {
    const phase = sample / 600;
    if (phase >= geometry.contactStartPhase
      && phase <= geometry.contactEndPhase) continue;
    const state = atPhase(phase);
    assert.ok(state.guardStudContacts.length >= 1,
      'at least one stud remains locked throughout every dwell');
    for (const contact of state.guardStudContacts) {
      assert.ok(contact.error < 1e-12);
    }
  }

  for (const phase of [
    0.05,
    0.1,
    geometry.contactStartPhase,
    geometry.contactStartPhase + geometry.contactPhaseSpan / 2,
    geometry.contactEndPhase,
    0.24,
    0.5,
  ]) {
    const time = ((phase - geometry.initialCyclePhase) * geometry.fullTurn)
      / geometry.driverAngularSpeed;
    model.update(time, 0.016);
    const state = model.root.userData.kinematics;
    assert.equal(driver.userData.rotor.rotation.z, state.driverAngle);
    assert.equal(driverShaft.userData.rotor.rotation.z, state.driverAngle);
    assert.equal(driven.userData.rotor.rotation.z, state.drivenAngle);
    assert.equal(drivenShaft.userData.rotor.rotation.z, state.drivenAngle);
    assert.equal(model.root.userData.contacts.guardStuds.engaged,
      state.guardLockEngaged);
    assert.equal(model.root.userData.contacts.tappetStud.engaged,
      state.tappetStudEngaged);
    assert.equal(model.root.userData.contacts.guardStuds.contacts.length,
      state.guardStudContacts.length);
    model.root.updateMatrixWorld(true);
    const renderedActiveStudCenter = studs[state.activeStudIndex]
      .getWorldPosition(new THREE.Vector3());
    assert.ok(renderedActiveStudCenter.clone().setZ(0).distanceTo(
      state.activeStudCenter.clone().setZ(0),
    ) < 1e-11);
    if (state.tappetStudEngaged) {
      const renderedFacePoint = driver.userData.rotor.localToWorld(
        new THREE.Vector3(
          state.tappetContactProjection,
          -geometry.tappetHalfWidth,
          geometry.studContactPlaneZ,
        ),
      );
      assert.ok(renderedFacePoint.distanceTo(state.tappetFaceContactPoint)
        < 1e-11);
      assert.ok(model.root.userData.contacts.tappetStud.facePoint.distanceTo(
        state.studTappetContactPoint,
      ) < 1e-11);
    } else {
      for (const contact of model.root.userData.contacts.guardStuds.contacts) {
        assert.ok(contact.error < 1e-12);
        assert.ok(contact.guardPoint.distanceTo(contact.studPoint) < 1e-12);
      }
    }
  }
  disposeModel(model.root);
});

